const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southernCal = ee.Geometry.Polygon([
    [-124.5, 32.5], [-114.0, 32.5], [-114.0, 35.0], [-124.5, 35.0]
  ]);

  const date2003 = ['2003-04-14', '2003-04-22'];
  const date2004 = ['2004-04-14', '2004-04-22'];

  // 2. Data Acquisition - Use MODIS LST (MOD11A2)
  const getLST = (dateRange) => {
    return ee.ImageCollection('MODIS/061/MOD11A2')
      .filterBounds(southernCal)
      .filterDate(dateRange[0], dateRange[1])
      .select('LST_Day_1km');
  };

  const lst2003 = getLST(date2003);
  const lst2004 = getLST(date2004);

  // Check collection sizes
  const size2003 = lst2003.size().getInfo();
  const size2004 = lst2004.size().getInfo();

  console.log(`2003 Images: ${size2003}, 2004 Images: ${size2004}`);

  if (size2003 === 0 || size2004 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Process LST: Convert from Kelvin to Celsius
  const processCollection = (col) => {
    return col.mean()
      .multiply(0.02)  // Scale factor
      .subtract(273.15) // Kelvin to Celsius
      .rename('LST_C');
  };

  const lstImg2003 = processCollection(lst2003);
  const lstImg2004 = processCollection(lst2004);

  // Count valid pixels (excluding extreme values)
  const reducer = ee.Reducer.count();

  const count2003 = lstImg2003
    .reduceRegion({
      reducer: reducer,
      geometry: southernCal,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

  const count2004 = lstImg2004
    .reduceRegion({
      reducer: reducer,
      geometry: southernCal,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

  console.log(`Valid Pixels 2003: ${count2003}, 2004: ${count2004}`);

  if (count2003 === 0 || count2004 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean LST
  const meanReducer = ee.Reducer.mean();

  const mean2003 = lstImg2003
    .reduceRegion({
      reducer: meanReducer,
      geometry: southernCal,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

  const mean2004 = lstImg2004
    .reduceRegion({
      reducer: meanReducer,
      geometry: southernCal,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_C').getInfo();

  console.log(`Mean LST 2003: ${mean2003.toFixed(2)}°C`);
  console.log(`Mean LST 2004: ${mean2004.toFixed(2)}°C`);

  // Validate results
  if (mean2003 === null || mean2004 === null || 
      Math.abs(mean2003) > 100 || Math.abs(mean2004) > 100) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare temperatures
  const diff = mean2004 - mean2003;
  console.log(`Difference: ${diff.toFixed(2)}°C`);

  if (diff > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
